const sbVerdict=x=>x.verdict==='accepted'?'Aceptada':x.verdict==='rejected'?'Rechazada'+(x.rules?.length?': '+x.rules.join(', '):''):'Sin revisar',sbPillClass=x=>x.verdict==='accepted'?'ok':x.verdict==='rejected'?'bad':'warn',sbShown=m=>m?m.current||m.groups[0].takes.at(-1):null,sbWhen=d=>d?new Date(d).toLocaleString('es-ES',{dateStyle:'short',timeStyle:'short'}):'',sbTime=n=>Number.isFinite(n)?`${Math.floor(n/60)}:${String(Math.round(n%60)).padStart(2,'0')}`:'–',sbByLote=list=>{const g=x=>x.lote??'Versiones';return [...new Set(list.map(g))].map(l=>[l,list.filter(x=>g(x)===l)]);};
